   v[2] = a[2] * b[2] + a[3] * b[3];
   v[2] = v[2] + v[2];
   v[3] = a[2] * b[3] - a[3] * b[2];
   if( v[3] >= 0. ) {
      v[4] = 3.14159265358979;
   } else {
      v[4] = -3.14159265358979;
   }
